source.loginUrl:
A = () =>{
	 let v = String(source.getVariable()).split(",");
    x=v[0];
	  if(x == 0) {
	  	  java.toast('\n'+URL())
	  	}
	  	if(x == 1) {
	  	  java.toast('\n'+URL())
	  	}
	  	if(x == 2) {
	  	  java.toast('\n'+URL())
	  	}
}

B = (x) =>{
	let v = String(source.getVariable()).split(",");
	 v[0]=x;
	source.setVariable(v.join(","));
	  if(x === 0){
	   	java.toast('\n'+'成功设置 '+URL());
	  	}
	  	if(x === 1){
	   	java.toast('\n'+'成功设置 '+URL());
	  	}
	  	if(x === 2){
	   	java.toast('\n'+'成功设置 '+URL());
	  	}
}

