@js:(function(){
var UA='Mozilla/5.0 (Linux; Android 13; SM-G991B) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/131.0.0.0 Mobile Safari/537.36';
// 默认兜底线路（与发布页当前 4 条一致）；实际线路来自登录面板「一键从发布页获取」写入的 om_lines
var DEF_LINES=['https://www.omofuns.com','https://cn.233dm.com','https://cn.211dm.com','https://cn.agekkkk.com'];
function lines(){
  var raw=SV('om_lines'),a=null;
  if(raw){try{a=JSON.parse(String(raw));}catch(e){a=null;}}
  if(a&&a.length){
    var r=[],seen={};
    for(var i=0;i<a.length;i++){
      var u=(typeof a[i]==='string')?a[i]:(a[i]&&a[i].u?String(a[i].u):'');
      u=String(u).replace(/\/+$/,'');
      if(u.indexOf('https://')===0&&u.indexOf('fb.omoo')<0&&!seen[u]){seen[u]=1;r.push(u);}
    }
    if(r.length)return r;
  }
  // 兼容旧书源遗留的 om_sn / om_s1..8
  var n=parseInt(SV('om_sn'),10)||0,r2=[];
  for(var j=1;j<=n&&j<=8;j++){var v=SV('om_s'+j).replace(/\/+$/,'');if(v.indexOf('https://')===0)r2.push(v);}
  if(r2.length)return r2;
  return DEF_LINES;
}
var K=[78,63,169,194,18,125,136,239,85,170,11,205,222,173,190,239];
function S(v){try{var s=String(v==null?'':v);return (s==='null'||s==='undefined'||s==='[object Object]'||s==='JsNull')?'':s;}catch(e){return '';}}
function SV(k){try{return S(source.get(k));}catch(e){return '';}}
function sub(k,v){try{source.put(k,String(v));}catch(e){}}
function curLine(){var c=SV('om_line').replace(/\/+$/,''),a=lines();if(c.indexOf('https://')===0&&c.indexOf('fb.omoo')<0){for(var i=0;i<a.length;i++)if(a[i]===c)return c;if(c===SV('om_custom').replace(/\/+$/,''))return c;}return a[0];}
function hostOf(u){var s=String(u==null?'':u),m=/^https?:\/\/([^\/]+)/.exec(s);if(!m)return '';var hn=m[1],a=lines();for(var i=0;i<a.length;i++){if(a[i].replace(/^https?:\/\//,'')===hn)return a[i];}if(s.indexOf('https://')===0)return 'https://'+hn;return '';}
function ord(){var c=curLine(),a=lines(),r=[c];for(var i=0;i<a.length;i++){if(a[i]!==c)r.push(a[i]);}return r;}
