    title: title,
    url: url,
    style: {
        layout_flexGrow: basis1,
        layout_flexBasisPercent: basis2
    }
});
List =[ 
["全部分类","sort/"],
["玄幻奇幻","sort/1/"],
["武侠修真","sort/2/"],
["都市言情","sort/3/"],
["网游动漫","sort/4/"],
["科幻小说","sort/5/"],
["恐怖灵异","sort/6/"],
["其他类型","sort/7/"],

["🔥完结小说🔥","title"],　　
["全部分类","quanben/sort/"],
["玄幻奇幻","quanben/sort/1/"],
["武侠修真","quanben/sort/2/"],
["都市言情","quanben/sort/3/"],
["网游动漫","quanben/sort/4/"],
["科幻小说","quanben/sort/5/"],
["恐怖灵异","quanben/sort/6/"],
["其他类型","quanben/sort/7/"]
];
push("🔥分类小说🔥",null,1,1);
List.map(([tag, url]) => {
    url = `${baseUrl}/${url}{{page}}/`;
    if (tag.startsWith("🔥")) {
        push(tag, url, 1, 1);
    } else {
        push(tag, url, 1, 0.33);
    }
});
JSON.stringify(sort);

